// Spring Boot's internal DataSourceAutoConfiguration (simplified)
@Configuration
@ConditionalOnClass(DataSource.class)  // Only if JDBC driver JAR exists
@ConditionalOnProperty(name = "spring.datasource.url")  // Only if URL configured
public class DataSourceAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean  // Only if you haven't defined your own
    public DataSource dataSource(DataSourceProperties properties) {
        var config = new HikariConfig();
        config.setJdbcUrl(properties.getUrl());
        config.setUsername(properties.getUsername());
        config.setPassword(properties.getPassword());
        return new HikariDataSource(config);  // Creates connection pool
    }

    @Bean
    public JdbcTemplate jdbcTemplate(DataSource dataSource) {
        return new JdbcTemplate(dataSource);  // Auto-wires the DataSource above
    }
}

// Inside spring-boot-autoconfigure JAR:
// META-INF/spring/org.springframework.boot.autoconfigure.AutoConfiguration.imports
