org.springframework.boot.autoconfigure.transaction.TransactionAutoConfiguration
*/

// At runtime, Boot's AutoConfigurationImportSelector reads this file:
public class AutoConfigurationImportSelector {

    protected List<String> getCandidateConfigurations() {
        var configurations = SpringFactoriesLoader.loadFactoryNames(
            AutoConfiguration.class,  // Looks for AutoConfiguration.imports files
            getClass().getClassLoader()
        );
        return configurations;  // Returns list of class names to load
    }
}

// Spring Boot's auto-configuration for RestTemplate (simplified)
@Configuration
public class RestTemplateAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean  // Only if no RestTemplate exists
    public RestTemplate restTemplate(RestTemplateBuilder builder) {
        return builder.build();  // Default: no special config
    }
}

// Your application configuration overrides the default
@Configuration
public class AppConfig {

    @Bean
    public RestTemplate restTemplate() {
        var template = new RestTemplate();
        // Custom timeout settings
        var factory = new SimpleClientHttpRequestFactory();
        factory.setConnectTimeout(3000);
        factory.setReadTimeout(5000);
        template.setRequestFactory(factory);
        return template;  // This bean is created FIRST
    }
}

// Result: Your RestTemplate is used everywhere.
// Boot's auto-config sees your bean and skips creating its default.
